        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("registrationDate"));
        return ResponseEntity.status(status).body(detail);
    }

}
